--
-- Name: unloading_rates; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.unloading_rates (
    id integer NOT NULL,
    party_id integer NOT NULL,
    unit_number integer,
    unit_name character varying(150) NOT NULL,
    route_id integer,
    rate_per_ton numeric(12,2) NOT NULL,
    description character varying(255),
    status character varying(10) DEFAULT 'ACTIVE'::character varying NOT NULL,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    CONSTRAINT unloading_rates_rate_per_ton_check CHECK ((rate_per_ton >= (0)::numeric)),
    CONSTRAINT unloading_rates_status_check CHECK (((status)::text = ANY ((ARRAY['ACTIVE'::character varying, 'INACTIVE'::character varying])::text[])))
);


ALTER TABLE public.unloading_rates OWNER TO postgres;

