--

CREATE TABLE public.vehicles (
    id integer NOT NULL,
    lorry_number character varying(20) NOT NULL,
    vehicle_type character varying(50),
    capacity_tons numeric(10,2),
    status character varying(10) DEFAULT 'ACTIVE'::character varying NOT NULL,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    goodshed_loading_expense numeric(10,2) DEFAULT 0,
    rc_number character varying(50),
    rc_photo_url text,
    account_number character varying(50),
    bank_name character varying(100),
    ifsc_code character varying(30),
    account_holder_name character varying(100),
    account_photo_url text,
    pan_number character varying(20),
    pan_card_url text,
    dts_number character varying(50),
    dts_expiry_date date,
    dts_certificate_url text,
    insurance_policy_number character varying(100),
    insurance_expiry_date date,
    insurance_photo_url text,
    permit_number character varying(100),
    permit_expiry_date date,
    permit_photo_url text,
    fc_number character varying(100),
    fc_expiry_date date,
    fc_photo_url text,
    tax_expiry_date date,
    tax_photo_url text,
    rc_expiry_date date,
    rc_photo_back_url text,
    truck_image_url text,
    rc_reg_date date,
    tds_number character varying(50),
    tds_expiry_date date,
    tds_certificate_url text,
    license_number character varying(30),
    license_expiry_date date,
    license_photo_url text,
    license_photo_back_url text,
    tds_certificate_url_2 text,
    CONSTRAINT vehicles_status_check CHECK (((status)::text = ANY ((ARRAY['ACTIVE'::character varying, 'INACTIVE'::character varying])::text[])))
);


ALTER TABLE public.vehicles OWNER TO postgres;

